  // selected; kinds with no WORKFLOW_CONNECT_DEFS entry yield empty menus
  // and the host renders nothing (future kinds degrade gracefully).
  const connectorNode = useMemo(() => {
    // Pure single-node selection only — a mixed selection (node + wb
    // items) shows the group align bar instead.
    if (selectedNodeIds.size !== 1 || !selectedNodeId) return null;
    if (selectedWbIds.size > 0) return null;
    return (data.nodes || []).find(n => n.id === selectedNodeId) || null;
  }, [selectedNodeIds, selectedNodeId, selectedWbIds, data.nodes]);
  const connectorMenus = useMemo(() => {
    if (!connectorNode) return null;
    return {
      left:  workflowConnectMenu(connectorNode, "left"),
      right: workflowConnectMenu(connectorNode, "right"),
      leftBundles:  workflowConnectBundlesFor(connectorNode, "left"),
      rightBundles: workflowConnectBundlesFor(connectorNode, "right"),
    };
  }, [connectorNode && connectorNode.id, connectorNode && connectorNode.kind, connectorNode && connectorNode.skill]);
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    // Clear any stale data-connected flags first.
    for (const el of wrap.querySelectorAll('[data-connected="true"]')) {
      el.removeAttribute("data-connected");
    }
    if (!connectedNodeIds || connectedNodeIds.size === 0) return;
    for (const id of connectedNodeIds) {
      const el = wrap.querySelector(`[data-node-id="${CSS.escape(id)}"]`);
      if (el) el.setAttribute("data-connected", "true");
    }
  }, [connectedNodeIds]);
  // v2.9 — mirror selection + nodes into the parent's ref so chat-spawn
  // can read "what's selected right now" without re-plumbing state up.
  // The parent passes selectionRef only when it cares (workflow-mode chat
  // host); guard for absence so the component still works standalone.
  useEffect(() => {
    if (selectionRef) {
      selectionRef.current = {
        selectedIds: new Set(selectedNodeIds),
        nodes:       data?.nodes || [],
        // Whiteboard context for chat-spawn. wbMode gates whether the
        // <whiteboard> block enters the first message at all — in build
        // mode whiteboard content is deliberately invisible to agents.
        wbMode,
        wb:            data?.wb || [],
        selectedWbIds: new Set(selectedWbIds),
      };
    }
    // v2.9b — push the reactive count up so the parent can show UI hints
    // (Send-button badge etc.). Cheap setState — only fires on change.
    if (onSelectionCountChange) onSelectionCountChange(selectedNodeIds.size);
    // Multi-select flag for body-portaled per-node chrome (top-action
    // strips / asset bars / badges hide via shouldHideNodeChrome and the
    // group align bar takes over). Body attribute because those components
    // render through createPortal and share no props with the surface.
    try {
      document.body.setAttribute("data-wf-multi-select",
        (selectedNodeIds.size + selectedWbIds.size) > 1 ? "true" : "false");
    } catch {}
  }, [selectedNodeIds, selectedWbIds, wbMode, data?.nodes, data?.wb, selectionRef, onSelectionCountChange]);

  // v2.4b — same imperative pattern for data-selected. Most node kinds set
  // this attribute via a `selected` prop already, but kinds added after
  // v2.4 (skill=llm via WorkflowSkillNode's llm branch) do
  // not. Setting it imperatively at the wrap level catches every kind
  // without per-component prop plumbing. When a component DOES set its own
  // data-selected via prop, this effect runs after the re-render and
  // converges to the same value — no correctness issue.
  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    for (const el of wrap.querySelectorAll('[data-node-id][data-selected="true"]')) {
      el.removeAttribute("data-selected");
    }
    if (!selectedNodeId) return;
    const el = wrap.querySelector(`[data-node-id="${CSS.escape(selectedNodeId)}"]`);
    if (el) el.setAttribute("data-selected", "true");
  }, [selectedNodeId]);

  // Esc deselects every node (and any build-mode whiteboard selection).
  // Skipped when the focus is inside an editable element (textarea/input/
  // contenteditable) so the user can press Esc to leave a field without
  // also wiping the selection. Whiteboard MODE has its own Esc ladder.
  useEffect(() => {
    if (selectedNodeIds.size === 0 && selectedWbIds.size === 0) return;
    if (wbMode) return;  // the wb keydown effect owns Esc in whiteboard mode
    const onKey = (e) => {
      if (e.key !== "Escape") return;
      const t = e.target;
      const tag = t && t.tagName ? t.tagName.toUpperCase() : "";
      if (tag === "INPUT" || tag === "TEXTAREA" || (t && t.isContentEditable)) return;
      setSelectedNodeIds(new Set());
      setSelectedWbIds(new Set());
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selectedNodeIds, selectedWbIds, wbMode]);

  // Marquee selection state. `marquee` holds the in-progress rect in WORLD
  // coordinates (so pan/zoom can compose with it cleanly when rendering).
  // null when not dragging. The mousedown handler at .workflow-canvas-wrap
  // creates the rect; window mousemove extends it; mouseup commits the
  // intersecting node set + clears the rect.
  const [marquee, setMarquee] = useState(null);
