      const linkTags = (bundle.links || []).map(t => "  " + t).join("\n");
      const wrapAttr = bundle.rootInlineStyle ? ` style="${bundle.rootInlineStyle}"` : "";
      const standaloneHtml = [
        "<!doctype html>",
        '<html lang="en"><head>',
        '  <meta charset="utf-8">',
        `  <title>Snippet ${stamp}</title>`,
        linkTags,
        "  <style>",
        "    body { margin: 0; background: #fff; }",
        bundle.css || "",
        "  </style>",
        "</head>",
        "<body>",
        `  <div${wrapAttr}>`,
        "    " + clip.outerHTML,
        "  </div>",
        "</body></html>",
        "",
      ].join("\n");
