    const MOBILE_REF  = { w: 390,  h: 844,  cls: "mobile"  };
    // The downstream sizing block defines aspect as width / height, so:
    //   desktop aspect = 1440 / 900 = 1.6
    //   mobile aspect  = 390 / 844 ≈ 0.46
    const aspectFor = (ref) => ref.w / ref.h;

