  if (!ds) return null;
  const strictness = (opts && opts.strictness === "strict") ? "strict" : "loose";
  const colorTokens = _dsColorTokens(ds);
  const fontTokens = _dsFontTokens(ds);
  const allTokens = _dsAllTokens(ds);
  const violations = [];
  const warnings = [];

  // Walk style blocks + inline-style attributes. The output already gets
  // typography MANDATORY framing in the prompt; this is the after-the-fact
  // verification of whether the model actually obeyed.
  const styleContexts = _dsExtractStyleContexts(content);
