    for (const m of ctx.text.matchAll(fontShorthandRe)) {
      const fam = _extractFamilyFromShorthand(m[1]);
      if (fam) fontSources.push({ raw: fam, kind: "font-shorthand", fullSnippet: m[1].trim() });
    }
